import { TransformNode, SceneLoader, Vector3 } from '@babylonjs/core';

// 5cm KwK 39 L/60-inspired gun — ORIGINAL mesh, generated by
// scripts/modelgen/medium_gun_50mm.py. Slim long tube, small single-baffle brake.

export default {
  id: 'medium-gun-50mm',
  name: '50mm L/60',
  category: 'cannon',
  stats: {
    caliber: 50,
    barrelLength: 2.30,
    elevation: 20,
    depression: 10,
  },

  async build(scene, material) {
    const result = await SceneLoader.ImportMeshAsync(
      '', '/assets/models/tanks/parts/', 'medium_gun_50mm.glb', scene
    );

    const root = new TransformNode('gunMedium50_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) {
      m.setParent(root);
      m.material = material;
    }

    // Set rotation AFTER parenting — same reason as the other cannon modules.
    root.rotation.x = Math.PI / 2;

    return { root, meshes, breech: new Vector3(0, 0, 0) };
  },
};
